head.b:skin:
/*
<Group description="Theme colors" selector="body">
  <Variable name="accent.color" description="Accent color" type="color" default="#087d59" value="#087d59"/>
</Group>
*/
:root{--accent:$(accent.color);--accent-deep:#086c4d;--ink:#222b28;--muted:#63706a;--paper:#f7f7f7;--surface:#fff;--line:#e3e7e4;--soft:#edf4ed;--header:#22252d;--serif:Georgia,'Times New Roman',serif;--sans:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;--width:1320px}
html[data-theme='dark']{color-scheme:dark;--ink:#e7eee9;--muted:#a1afa6;--paper:#101a16;--surface:#182620;--line:#304038;--soft:#22372c;--accent:#73d4a7;--accent-deep:#a0e7c3;--header:#0c1712}
*,*:before,*:after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.6;-webkit-font-smoothing:antialiased}
img{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button,input{font:inherit}
button{cursor:pointer}
button,input,textarea{outline-offset:3px}
button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #4dcc94;outline-offset:3px}
svg{display:block;flex:none}
[hidden]{display:none!important}
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip-link{position:fixed;z-index:200;top:10px;left:10px;padding:10px 16px;background:#fff;color:#10271f;transform:translateY(-160%)}
.skip-link:focus{transform:translateY(0)}
.container{width:min(var(--width),calc(100% - 80px));margin-inline:auto}
.site-header{position:sticky;top:0;z-index:60;background:var(--header);color:#fff;transition:box-shadow .25s ease}
.site-header.is-scrolled{box-shadow:0 8px 28px rgba(0,0,0,.16)}
.header-inner{min-height:82px;display:flex;align-items:center;gap:35px}
.header-brand{flex:none;min-width:0}
.brand-link{display:inline-flex;align-items:center;gap:12px;max-width:360px;line-height:1}
.brand-mark{display:grid;place-items:center;width:36px;height:36px;color:#76dfad;flex:none}
.brand-lockup{display:flex;min-width:0;flex-direction:column;gap:4px}
.brand-name{font-family:var(--sans);font-size:24px;font-weight:800;letter-spacing:-.6px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.brand-tagline{color:#bcc7c0;font-size:10px;font-weight:600;line-height:1.1}
.brand-image{max-width:230px;max-height:48px;width:auto;height:auto;object-fit:contain}
.primary-nav{margin-left:auto}
.nav-list,.nav-submenu{list-style:none;margin:0;padding:0}
.nav-list{display:flex;align-items:center;gap:27px}
.nav-list>li{position:relative;display:flex;align-items:center;gap:4px}
.nav-list>li>a{display:block;padding:29px 0;color:#e6eee9;font-size:13px;font-weight:600;white-space:nowrap;transition:color .2s ease}
.nav-list a:hover,.nav-list a[aria-current='page']{color:#8be3b9}
.submenu-toggle{display:grid;place-items:center;border:0;padding:6px;color:#b9cdc1;background:transparent}
.submenu-toggle svg{transition:transform .2s ease}
.has-submenu.is-open>.submenu-toggle svg{transform:rotate(180deg)}
.nav-submenu{position:absolute;top:calc(100% - 8px);left:-19px;min-width:196px;padding:8px;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:8px;box-shadow:0 15px 35px rgba(0,0,0,.15)}
.nav-submenu a{display:block;padding:10px 12px;border-radius:5px;font-size:13px;font-weight:600}
.nav-submenu a:hover{background:var(--soft);color:var(--accent-deep)}
.header-actions{display:flex;align-items:center;gap:7px;flex:none}
.icon-button{width:40px;height:40px;display:grid;place-items:center;padding:0;border:1px solid rgba(255,255,255,.14);border-radius:6px;background:transparent;color:#fff;transition:background .2s,border-color .2s}
.icon-button:hover{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.32)}
.theme-sun{display:none}
html[data-theme='dark'] .theme-sun{display:block}
html[data-theme='dark'] .theme-moon{display:none}
.header-cta{display:inline-flex;align-items:center;justify-content:center;min-height:41px;padding:0 17px;margin-left:5px;border-radius:5px;background:#343943;color:#fff;font-size:12px;font-weight:800;white-space:nowrap;transition:background .2s,transform .2s}
.header-cta:hover{background:#49515b;transform:translateY(-2px)}
.menu-toggle{display:none}
.header-search{border-top:1px solid rgba(255,255,255,.12);padding:17px 0}
.header-search form{display:flex;max-width:690px;margin:auto;gap:10px}
.header-search input{min-width:0;flex:1;border:1px solid #547064;border-radius:5px;padding:11px 14px;color:#fff;background:#203b30}
.header-search input::placeholder{color:#b5c9bd}
.header-search button{padding:0 20px;border:0;border-radius:5px;background:#c5f1d9;color:#123327;font-weight:700}
.hero{position:relative;display:grid;place-items:center;min-height:485px;overflow:hidden;background:#0b9e70;color:#fff;isolation:isolate}
.hero-photo{position:absolute;z-index:-3;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 54%;animation:hero-image 1.2s ease both}
.hero:before{content:'';position:absolute;z-index:-2;inset:0;background:linear-gradient(100deg,rgba(8,112,79,.86),rgba(0,125,85,.84))}
.hero:after{content:'';position:absolute;z-index:-1;inset:0;background:linear-gradient(180deg,rgba(5,70,45,.08),transparent 45%,rgba(4,65,42,.12))}
.hero-content{width:min(1000px,calc(100% - 40px));padding:58px 0 65px;text-align:center}
.hero-eyebrow{display:flex;align-items:center;justify-content:center;gap:10px;margin:0 0 14px;color:#f0fff4;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;animation:rise-in .65s .05s both}
.hero-eyebrow:before,.hero-eyebrow:after{content:'';width:27px;height:1px;background:rgba(211,249,228,.6)}
.hero h1{margin:0;font-size:clamp(31px,3.6vw,51px);line-height:1.15;letter-spacing:-.035em;font-weight:750;animation:rise-in .7s .13s both}
.hero-subtitle{margin:18px auto 23px;color:#f2fff6;font-size:15px;animation:rise-in .7s .2s both}
.hero-search{display:flex;align-items:center;max-width:630px;min-height:59px;margin:0 auto;background:#fff;border-radius:999px;box-shadow:0 12px 35px rgba(0,0,0,.1);animation:rise-in .7s .27s both}
.hero-search input{width:100%;min-width:0;flex:1;height:57px;padding:0 24px;border:0;background:transparent;color:#20352a;outline:none;font-size:14px}
.hero-search input::placeholder{color:#66766d}
.hero-search:focus-within{outline:3px solid #a6e7c4;outline-offset:3px}
.hero-search button{display:grid;place-items:center;width:48px;height:43px;margin:7px 9px 7px 0;padding:0;border:0;border-radius:50%;background:transparent;color:#7e8c84;transition:background .2s,color .2s}
.hero-search button:hover{background:#edf6ef;color:#087d59}
.featured-link{display:inline-flex;align-items:center;gap:7px;margin-top:23px;color:#fff;font-size:12px;font-weight:650;animation:rise-in .7s .33s both}
.featured-link svg{transition:transform .2s}
.featured-link:hover svg{transform:translateX(4px)}
.featured-link span{max-width:290px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.page-main{min-height:360px}
.ad-region .widget{margin:25px auto;max-width:100%;overflow:hidden;text-align:center}
.ad-region:empty,.section:empty{display:none}
.listing-intro{display:flex;justify-content:space-between;align-items:end;gap:20px;padding-top:53px}
.homepage-listing .listing-intro{padding-top:0}
.homepage-listing .catalog-toolbar{margin-top:0;border-top:0}
.eyebrow{margin:0 0 8px;color:var(--accent);font-size:10px;font-weight:800;letter-spacing:.16em;line-height:1.3;text-transform:uppercase}
.listing-intro h1,.listing-intro h2{margin:0;font-family:var(--serif);font-size:clamp(28px,2.6vw,37px);line-height:1.15;letter-spacing:-.035em}
.listing-intro p:not(.eyebrow){margin:9px 0 0;color:var(--muted);font-size:13px}
.text-link{display:inline-flex;align-items:center;gap:9px;color:var(--accent-deep);font-size:12px;font-weight:800;white-space:nowrap}
.text-link svg{transition:transform .2s}
.text-link:hover svg{transform:translateX(4px)}
.catalog-toolbar{display:flex;align-items:center;gap:20px;margin-top:25px;padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.filter-heading{display:inline-flex;align-items:center;gap:9px;color:var(--ink);font-size:13px;font-weight:800;white-space:nowrap}
.catalog-note{color:var(--muted);font-size:11px}
.catalog-controls{display:flex;align-items:center;gap:14px;margin-left:auto}
.view-controls{display:flex;gap:3px}
.view-button{display:grid;place-items:center;width:34px;height:34px;padding:0;border:1px solid transparent;background:transparent;color:var(--muted);border-radius:3px}
.view-button[aria-pressed='true']{border-color:var(--line);background:var(--surface);color:var(--ink)}
.sort-control{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:11px;white-space:nowrap}
.sort-control select{max-width:155px;padding:8px 26px 8px 10px;border:1px solid var(--line);border-radius:3px;background:var(--surface);color:var(--ink);font:inherit;font-weight:700}
.topic-section{margin-top:18px;border-bottom:1px solid var(--line)}
.topic-tabs{display:flex;align-items:center;gap:29px;overflow-x:auto;scrollbar-width:none}
.topic-tabs::-webkit-scrollbar{display:none}
.topic-tabs a{position:relative;display:block;padding:0 0 15px;color:var(--muted);font-size:12px;font-weight:750;white-space:nowrap;transition:color .2s}
.topic-tabs a:hover,.topic-tabs a.current{color:var(--ink)}
.topic-tabs a.current:after{content:'';position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--accent)}
.content-layout{display:grid;grid-template-columns:minmax(0,1fr) 275px;gap:43px;padding-top:31px;padding-bottom:65px;align-items:start}
.content-layout.listing-layout{grid-template-columns:minmax(0,1fr)}
.content-layout.listing-layout>.sidebar{display:none}
.content-layout.single-layout{padding-top:48px}
.posts-column{min-width:0}
.post-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.post-grid.list-view{grid-template-columns:minmax(0,1fr)}
.list-view .post-card>a{flex-direction:row}
.list-view .card-media{width:32%;flex:none;min-height:170px}
.post-card{min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:7px;overflow:hidden;transition:border-color .25s,box-shadow .25s,transform .25s}
.post-card:hover{transform:translateY(-4px);border-color:#bad8c4;box-shadow:0 12px 30px rgba(27,58,40,.08)}
.post-card>a{display:flex;min-height:100%;flex-direction:column}
.card-media{position:relative;aspect-ratio:1.55;background:#d9e8dd;overflow:hidden}
.card-media img{width:100%;height:100%;object-fit:cover;transition:transform .55s cubic-bezier(.2,.7,.2,1)}
.post-card:hover .card-media img{transform:scale(1.045)}
.card-noimage{height:100%;display:grid;place-items:center;background:#dbe9df;color:#568570}
.card-noimage svg{width:58px;height:58px;opacity:.65}
.card-body{display:flex;flex:1;flex-direction:column;padding:18px 18px 16px}
.card-category{color:var(--accent);font-size:10px;font-weight:800;letter-spacing:.07em;text-transform:uppercase}
.card-body h3{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;margin:7px 0 5px;overflow-wrap:anywhere;font-family:var(--sans);font-size:16px;font-weight:750;letter-spacing:-.01em;line-height:1.38}
.card-excerpt{display:none;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;margin:0;color:var(--muted);font-size:12px;line-height:1.6}
.card-meta{display:flex;align-items:center;gap:7px;margin-top:auto;padding-top:19px;color:var(--muted);font-size:11px}
.card-meta .card-read{margin-left:auto}
.card-meta .card-read+.card-arrow{margin-left:0}
.card-byline{color:var(--muted);font-size:11px;line-height:1.4}
.card-byline em{font-family:var(--serif);font-style:italic}
.card-meta .dot{color:#aebbb1}
.card-arrow{display:grid;place-items:center;width:26px;height:26px;margin-left:auto;border:1px solid var(--line);border-radius:50%;color:var(--ink);transition:background .2s,color .2s,border-color .2s}
.post-card:hover .card-arrow{background:var(--accent);color:#fff;border-color:var(--accent)}
.card-read{color:var(--accent-deep);font-size:11px;font-weight:800;white-space:nowrap}
.empty-state{padding:55px 20px;border:1px solid var(--line);background:var(--surface);text-align:center}
.empty-state h2{margin:0 0 8px;font-family:var(--serif);font-size:25px}
.empty-state p{margin:0 0 18px;color:var(--muted)}
.pagination{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:35px}
.pagination a{display:inline-flex;align-items:center;gap:8px;padding:10px 14px;border:1px solid var(--line);border-radius:5px;background:var(--surface);font-size:12px;font-weight:750;transition:border-color .2s,color .2s}
.pagination a:hover{border-color:var(--accent);color:var(--accent)}
.pagination .older{margin-left:auto}
.sidebar{min-width:0}
.sidebar .widget{margin-bottom:35px}
.widget-title{margin:0 0 18px;padding-bottom:12px;border-bottom:1px solid var(--line);font-family:var(--serif);font-size:19px;letter-spacing:-.025em}
.widget-title:after{content:'';display:block;width:32px;height:2px;margin-bottom:-14px;margin-top:12px;background:var(--accent)}
.popular-list,.label-list,.footer-links{list-style:none;margin:0;padding:0}
.popular-list{counter-reset:popular}
.popular-list li{counter-increment:popular;border-bottom:1px solid var(--line)}
.popular-list a{display:grid;grid-template-columns:25px 1fr 67px;align-items:center;gap:9px;padding:13px 0}
.popular-list.no-thumbs a{grid-template-columns:25px 1fr}
.popular-list a:before{content:counter(popular,decimal-leading-zero);color:#a7b7ad;font-family:var(--serif);font-size:17px;font-style:italic}
.popular-copy{min-width:0}
.popular-category{display:block;color:var(--accent);font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
.popular-copy strong{display:block;margin-top:3px;font-size:12px;line-height:1.45;transition:color .2s}
.popular-list a:hover strong{color:var(--accent)}
.popular-image,.popular-placeholder{width:67px;height:58px;object-fit:cover;border-radius:4px;background:var(--soft)}
.label-list li{border-bottom:1px solid var(--line)}
.label-list a{display:flex;align-items:center;justify-content:space-between;padding:10px 0;color:var(--muted);font-size:12px;font-weight:650}
.label-list a:hover{color:var(--accent)}
.label-count{color:#9aa9a0;font-size:11px}
.sidebar .HTML,.sidebar .Text,.sidebar .BlogArchive{font-size:13px;color:var(--muted)}
.sidebar .HTML h2,.sidebar .Text h2,.sidebar .BlogArchive h2{color:var(--ink);font-family:var(--serif);font-size:19px}
.sidebar .widget img{max-width:100%;height:auto}
.sidebar .widget img.popular-image{height:58px}
.shelves-wrapper{min-height:1px;padding-bottom:20px}
.category-shelf{margin:0 0 56px}
.shelf-heading,.related-heading{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:21px}
.shelf-heading h2,.related-heading h2{margin:0;font-family:var(--serif);font-size:28px;letter-spacing:-.035em;line-height:1.2}
.shelf-grid,.related-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.shelf-grid .card-body,.related-grid .card-body{padding:16px}
.shelf-grid .card-body h3,.related-grid .card-body h3{font-size:17px}
.breadcrumb{margin:0 0 20px;color:var(--muted);font-size:11px;font-weight:650}
.breadcrumb ol{display:flex;flex-wrap:wrap;align-items:center;gap:9px;list-style:none;margin:0;padding:0}
.breadcrumb li+li:before{content:'/';margin-right:9px;color:#a2b1a6}
.breadcrumb a:hover{color:var(--accent)}
.article-page{min-width:0}
.article-head{padding-bottom:24px;border-bottom:1px solid var(--line)}
.article-kicker{display:inline-block;margin-bottom:12px;color:var(--accent);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}
.article-head h1{max-width:900px;margin:0;font-family:var(--serif);font-size:clamp(34px,4vw,54px);line-height:1.1;letter-spacing:-.045em}
.article-byline{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:19px;color:var(--muted);font-size:12px}
.article-byline strong{color:var(--ink)}
.article-body{margin-top:30px;color:var(--ink);font-size:16px;line-height:1.85;overflow-wrap:anywhere}
.article-body img{max-width:100%;height:auto;border-radius:5px}
.article-body iframe,.article-body video{max-width:100%}
.article-body h2,.article-body h3,.article-body h4{scroll-margin-top:100px;margin:1.6em 0 .55em;font-family:var(--serif);line-height:1.25;letter-spacing:-.025em}
.article-body h2{font-size:29px}.article-body h3{font-size:23px}
.article-body p{margin:0 0 1.25em}
.article-body a{color:var(--accent-deep);text-decoration:underline;text-underline-offset:3px}
.article-body blockquote{margin:1.5em 0;padding:2px 0 2px 22px;border-left:3px solid var(--accent);color:var(--muted);font-family:var(--serif);font-size:20px;font-style:italic}
.article-body pre{overflow:auto;padding:20px;background:#13251c;color:#e5f6e9;border-radius:5px;font-size:13px;line-height:1.7}
.article-body table{display:block;max-width:100%;overflow:auto;border-collapse:collapse}
.article-body th,.article-body td{padding:10px;border:1px solid var(--line)}
.article-toc{margin:27px 0 0;padding:15px 19px;border:1px solid var(--line);border-radius:6px;background:var(--surface)}
.article-toc summary{cursor:pointer;font-weight:800;font-size:13px}
.article-toc ol{margin:11px 0 2px;padding-left:21px;color:var(--muted);font-size:13px}
.article-toc li{padding:3px 0}
.article-toc .toc-sub{margin-left:16px;font-size:12px}
.article-toc a:hover{color:var(--accent)}
.post-labels{display:flex;flex-wrap:wrap;gap:8px;margin-top:30px}
.post-labels a{padding:5px 10px;background:var(--soft);color:var(--accent-deep);border-radius:3px;font-size:11px;font-weight:700}
.author-box{display:flex;gap:18px;align-items:start;margin-top:36px;padding:25px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.author-avatar,.author-fallback{width:56px;height:56px;flex:none;object-fit:cover;border-radius:50%;background:var(--soft)}
.author-fallback{display:grid;place-items:center;color:var(--accent);font-family:var(--serif);font-size:23px;font-weight:700}
.author-box .eyebrow{margin-bottom:4px}
.author-name{font-family:var(--serif);font-size:19px;font-weight:700}
.author-name:hover{color:var(--accent)}
.author-box p:last-child{margin:5px 0 0;color:var(--muted);font-size:12px}
.related{margin-top:45px}
.comments-wrap{margin-top:45px;overflow-wrap:anywhere}
.comments-wrap h2,.comments-wrap h3{font-family:var(--serif)}
.comments-wrap iframe{max-width:100%}
.reading-progress{position:fixed;z-index:100;top:0;left:0;width:0;height:3px;background:#76dfad;pointer-events:none}
.site-footer{background:#23252b;color:#ecf5ee}
.footer-main{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:90px;padding-top:54px;padding-bottom:53px}
.footer-brand .brand-link{margin-bottom:17px}
.footer-brand p{max-width:335px;margin:0;color:#aebfb4;font-size:13px;line-height:1.8}
.footer-follow{display:inline-flex;align-items:center;gap:8px;margin-top:20px;color:#a8e7c3;font-size:12px;font-weight:750}
.footer-follow:hover{text-decoration:underline;text-underline-offset:4px}
.footer-widgets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:45px}
.footer-widgets .widget{min-width:0}
.footer-widgets h2{margin:3px 0 16px;color:#fff;font-size:12px;font-weight:800;letter-spacing:.04em}
.footer-links li{margin:10px 0}
.footer-links a,.footer-widgets .widget-content{color:#b7c5bc;font-size:12px}
.footer-links a:hover{color:#b5efcc}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1)}
.footer-bottom-inner{display:flex;justify-content:space-between;gap:20px;padding-top:18px;padding-bottom:18px;color:#a5b6aa;font-size:11px}
.footer-bottom a:hover{color:#fff}
@keyframes rise-in{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@keyframes hero-image{from{transform:scale(1.045);opacity:.75}to{transform:scale(1);opacity:1}}
@media(max-width:1100px){.header-inner{gap:22px}.nav-list{gap:18px}.content-layout{grid-template-columns:minmax(0,1fr) 240px;gap:28px}}
@media(max-width:860px){.container{width:min(100% - 48px,var(--width))}.header-inner{min-height:72px}.brand-name{font-size:23px}.menu-toggle{display:grid}.header-cta{display:none}.primary-nav{position:absolute;top:100%;left:0;right:0;margin:0;padding:0 24px 16px;background:var(--header);border-top:1px solid rgba(255,255,255,.1)}html.js .primary-nav{display:none}html.js .primary-nav.is-open{display:block}.nav-list{display:block}.nav-list>li{display:flex;flex-wrap:wrap;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08)}.nav-list>li>a{flex:1;padding:13px 0}.submenu-toggle{padding:10px}.nav-submenu{position:static;width:100%;padding:0 0 10px 12px;border:0;border-radius:0;box-shadow:none;background:transparent;color:#c2d4c8}.nav-submenu a{padding:8px 0}.nav-submenu a:hover{background:transparent}.header-actions{margin-left:auto}.hero{min-height:455px}.content-layout{grid-template-columns:minmax(0,1fr) 215px;gap:24px}.footer-main{gap:45px}}
@media(max-width:640px){.container{width:calc(100% - 36px)}.header-inner{min-height:67px;gap:10px}.brand-link{gap:7px}.brand-mark{width:30px;height:30px}.brand-name{max-width:185px;font-size:20px;letter-spacing:-.7px}.brand-tagline{font-size:9px}.brand-image{max-width:170px}.header-actions{gap:5px}.icon-button{width:37px;height:37px}.hero{min-height:430px}.hero-content{padding:48px 0 53px}.hero h1{font-size:clamp(31px,7vw,43px)}.hero-break{display:none}.hero-subtitle{max-width:360px;font-size:13px}.hero-search{min-height:55px}.hero-search input{height:53px;font-size:13px}.hero-search button{height:40px;width:42px;margin:6px 8px 6px 0;padding:0}.listing-intro{padding-top:40px}.listing-intro p:not(.eyebrow){font-size:12px}.listing-intro .text-link,.catalog-note{display:none}.catalog-toolbar{gap:8px}.catalog-controls{gap:5px}.sort-control>span{display:none}.sort-control select{max-width:120px}.topic-section{margin-top:18px}.topic-tabs{gap:23px}.content-layout,.content-layout.single-layout{display:block;padding-top:25px;padding-bottom:44px}.post-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.list-view .card-media{width:37%;min-height:0}.card-media{aspect-ratio:1.35}.card-body{padding:13px}.card-body h3{font-size:14px}.card-excerpt{display:none}.card-meta{padding-top:12px;font-size:10px}.card-meta time{display:none}.card-meta .card-read{margin-left:0}.card-meta .card-arrow{margin-left:auto}.sidebar{margin-top:44px}.sidebar .widget{margin-bottom:29px}.shelf-grid,.related-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.category-shelf{margin-bottom:40px}.shelf-heading h2,.related-heading h2{font-size:24px}.footer-main{grid-template-columns:1fr;gap:32px;padding-top:42px;padding-bottom:38px}.footer-widgets{gap:24px}.footer-bottom-inner{display:block}.footer-bottom-inner>span{display:block}.footer-bottom-inner>span+span{margin-top:5px}.article-head h1{font-size:35px}.article-body{font-size:15px}.article-body h2{font-size:25px}}
@media(max-width:360px){.brand-name{max-width:140px}.post-grid{grid-template-columns:1fr}.card-media{aspect-ratio:1.6}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

head.b:template-skin:
body#layout{width:1000px;margin:0 auto;background:#f5f7f4;color:#1b2d22}
body#layout .site-header,body#layout .site-footer{position:static;background:#e6eee7;color:#1b2d22}
body#layout .header-inner,body#layout .footer-main,body#layout .content-layout,body#layout .footer-widgets{display:block;width:100%;padding:10px}
body#layout .primary-nav{position:static;display:block;padding:0}
body#layout .hero{display:block;min-height:0;background:#e6eee7;color:#1b2d22}
body#layout .hero-photo,body#layout .hero-content,body#layout .listing-intro,body#layout .header-actions,body#layout .footer-brand,body#layout .footer-bottom{display:none}
body#layout .section{margin:10px 0;min-height:50px}
body#layout .sidebar,body#layout .posts-column{display:block;width:100%;margin:0}
body#layout .content-layout.listing-layout>.sidebar{display:block}
body#layout .shelves-wrapper{display:block}

body.script:
//
  (function () {
    'use strict';
    var root = document.documentElement;
    var header = document.getElementById('siteHeader');
    var menuButton = document.getElementById('menuToggle');
    var nav = document.getElementById('primaryNav');
    var searchButton = document.getElementById('searchToggle');
    var searchPanel = document.getElementById('headerSearch');
    var themeButton = document.getElementById('themeToggle');
    var year = document.getElementById('copyrightYear');
    if (year) year.textContent = new Date().getFullYear();
    var heroYear = document.getElementById('heroYear');
    if (heroYear) heroYear.textContent = new Date().getFullYear();

    function setMenu(open) {
      if (!menuButton || !nav) return;
      nav.classList.toggle('is-open', open);
      menuButton.setAttribute('aria-expanded', String(open));
      menuButton.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation');
    }
    function setSearch(open) {
      if (!searchButton || !searchPanel) return;
      searchPanel.hidden = !open;
      searchButton.setAttribute('aria-expanded', String(open));
      searchButton.setAttribute('aria-label', open ? 'Close search' : 'Open search');
      if (open) {
        setMenu(false);
        var input = document.getElementById('headerQuery');
        if (input) input.focus();
      }
    }
    if (menuButton) menuButton.addEventListener('click', function () {
      var open = menuButton.getAttribute('aria-expanded') !== 'true';
      setSearch(false);
      setMenu(open);
    });
    if (searchButton) searchButton.addEventListener('click', function () {
      setSearch(searchButton.getAttribute('aria-expanded') !== 'true');
    });
    function updateThemeButton() {
      if (!themeButton) return;
      var dark = root.getAttribute('data-theme') === 'dark';
      themeButton.setAttribute('aria-pressed', String(dark));
      themeButton.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode');
    }
    updateThemeButton();
    if (themeButton) themeButton.addEventListener('click', function () {
      var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      try { localStorage.setItem('nara-theme', next); } catch (e) {}
      updateThemeButton();
    });

    var postGrid = document.querySelector('.post-grid');
    var catalogControls = document.getElementById('catalogControls');
    var gridButton = document.getElementById('gridView');
    var listButton = document.getElementById('listView');
    var sortPosts = document.getElementById('sortPosts');
    if (postGrid && catalogControls && gridButton && listButton && sortPosts) {
      var cards = Array.prototype.slice.call(postGrid.children);
      cards.forEach(function (card, index) { card.dataset.originalOrder = String(index); });
      catalogControls.hidden = false;
      function setPostView(list) {
        postGrid.classList.toggle('list-view', list);
        gridButton.setAttribute('aria-pressed', String(!list));
        listButton.setAttribute('aria-pressed', String(list));
      }
      gridButton.addEventListener('click', function () { setPostView(false); });
      listButton.addEventListener('click', function () { setPostView(true); });
      sortPosts.addEventListener('change', function () {
        cards.sort(function (a, b) {
          if (sortPosts.value === 'title') {
            return a.querySelector('h3').textContent.trim().localeCompare(b.querySelector('h3').textContent.trim());
          }
          return Number(a.dataset.originalOrder) - Number(b.dataset.originalOrder);
        });
        cards.forEach(function (card) { postGrid.appendChild(card); });
      });
    }

    // Prefix a Link List item with an underscore to place it under the previous item.
    var navList = document.getElementById('navList');
    if (navList) {
      var parent = null;
      Array.prototype.slice.call(navList.children).forEach(function (item) {
        var link = item.querySelector('a');
        if (!link) return;
        var name = link.textContent.trim();
        if (name.charAt(0) === '_' && parent) {
          var owner = parent;
          link.textContent = name.replace(/^_+\s*/, '');
          var submenu = owner.querySelector('.nav-submenu');
          if (!submenu) {
            submenu = document.createElement('ul');
            submenu.className = 'nav-submenu';
            submenu.hidden = true;
            submenu.id = 'submenu-' + Array.prototype.indexOf.call(navList.children, owner);
            var toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'submenu-toggle';
            toggle.setAttribute('aria-label', 'Toggle ' + owner.querySelector('a').textContent.trim() + ' submenu');
            toggle.setAttribute('aria-expanded', 'false');
            toggle.setAttribute('aria-controls', submenu.id);
            toggle.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 9 6 6 6-6" stroke-linecap="round" stroke-linejoin="round"></path></svg>';
            toggle.addEventListener('click', function () {
              var open = toggle.getAttribute('aria-expanded') !== 'true';
              submenu.hidden = !open;
              toggle.setAttribute('aria-expanded', String(open));
              owner.classList.toggle('is-open', open);
            });
            owner.classList.add('has-submenu');
            owner.appendChild(toggle);
            owner.appendChild(submenu);
          }
          submenu.appendChild(item);
        } else {
          parent = item;
          try {
            var target = new URL(link.href, location.href);
            if (target.origin === location.origin && target.pathname === location.pathname && !target.search && !location.search) link.setAttribute('aria-current', 'page');
          } catch (e) {}
        }
      });
    }
    document.addEventListener('click', function (event) {
      if (nav && !nav.contains(event.target) && menuButton && !menuButton.contains(event.target)) setMenu(false);
      if (navList && !navList.contains(event.target)) {
        navList.querySelectorAll('.has-submenu').forEach(function (item) {
          var toggle = item.querySelector('.submenu-toggle');
          var submenu = item.querySelector('.nav-submenu');
          if (toggle && submenu) { toggle.setAttribute('aria-expanded', 'false'); submenu.hidden = true; item.classList.remove('is-open'); }
        });
      }
    });
    document.addEventListener('keydown', function (event) {
      if (event.key !== 'Escape') return;
      if (searchPanel && !searchPanel.hidden) { setSearch(false); searchButton.focus(); }
      if (menuButton && menuButton.getAttribute('aria-expanded') === 'true') { setMenu(false); menuButton.focus(); }
      if (navList) navList.querySelectorAll('.has-submenu').forEach(function (item) {
        var toggle = item.querySelector('.submenu-toggle');
        var submenu = item.querySelector('.nav-submenu');
        if (toggle && submenu) { toggle.setAttribute('aria-expanded', 'false'); submenu.hidden = true; item.classList.remove('is-open'); }
      });
    });

    var body = document.getElementById('articleBody');
    var toc = document.getElementById('articleToc');
    var tocLinks = document.getElementById('tocLinks');
    if (body && toc && tocLinks) {
      var headings = Array.prototype.slice.call(body.querySelectorAll('h2, h3')).filter(function (heading) { return heading.textContent.trim(); });
      if (headings.length > 1) {
        var usedIds = new Set();
        headings.forEach(function (heading, index) {
          var id = heading.id;
          if (!id || usedIds.has(id) || document.getElementById(id) !== heading) {
            var base = heading.textContent.toLowerCase().trim().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-') || 'section-' + (index + 1);
            id = base;
            var suffix = 2;
            while (document.getElementById(id) || usedIds.has(id)) id = base + '-' + suffix++;
            heading.id = id;
          }
          usedIds.add(id);
          var item = document.createElement('li');
          if (heading.tagName === 'H3') item.className = 'toc-sub';
          var link = document.createElement('a');
          link.href = '#' + encodeURIComponent(id);
          link.textContent = heading.textContent.trim();
          item.appendChild(link);
          tocLinks.appendChild(item);
        });
        toc.hidden = false;
      }
    }

    var progress = document.getElementById('readingProgress');
    var scrollScheduled = false;
    function updateScroll() {
      if (header) header.classList.toggle('is-scrolled', window.scrollY > 8);
      if (progress && body) {
        var bounds = body.getBoundingClientRect();
        var total = Math.max(1, body.offsetHeight - window.innerHeight);
        var percent = Math.min(100, Math.max(0, -bounds.top / total * 100));
        progress.style.width = percent + '%';
      }
      scrollScheduled = false;
    }
    window.addEventListener('scroll', function () {
      if (!scrollScheduled) { scrollScheduled = true; window.requestAnimationFrame(updateScroll); }
    }, { passive: true });
    updateScroll();

    var homeMeta = document.querySelector('meta[name="blog-home"]');
    var home = homeMeta && homeMeta.content;
    function safeUrl(value) {
      try {
        var url = new URL(value, location.href);
        return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : '';
      } catch (e) { return ''; }
    }
    function pathKey(value) {
      try { var url = new URL(value, location.href); return url.origin + url.pathname.replace(/\/$/, ''); } catch (e) { return ''; }
    }
    function createFeedCard(entry) {
      var alternate = (entry.link || []).find(function (link) { return link.rel === 'alternate' && link.href; });
      var href = alternate && safeUrl(alternate.href);
      if (!href || !entry.title || !entry.title.$t) return null;
      var article = document.createElement('article');
      article.className = 'post-card';
      var anchor = document.createElement('a');
      anchor.href = href;
      var media = document.createElement('div');
      media.className = 'card-media';
      var thumb = entry.media$thumbnail && safeUrl(entry.media$thumbnail.url);
      if (thumb) {
        var image = document.createElement('img');
        image.src = thumb.replace(/^http:/, 'https:').replace(/\/s72(-c)?\//, '/w640-h400-p-k-no-nu/').replace(/=s72(-c)?$/, '=w640-h400-p-k-no-nu');
        image.alt = '';
        image.width = 640;
        image.height = 400;
        image.loading = 'lazy';
        image.decoding = 'async';
        media.appendChild(image);
      } else {
        var placeholder = document.createElement('div');
        placeholder.className = 'card-noimage';
        placeholder.setAttribute('aria-hidden', 'true');
        placeholder.textContent = '+';
        media.appendChild(placeholder);
      }
      var content = document.createElement('div');
      content.className = 'card-body';
      var category = document.createElement('span');
      category.className = 'card-category';
      category.textContent = entry.category && entry.category.length ? entry.category[0].term : 'Journal';
      var title = document.createElement('h3');
      title.textContent = entry.title.$t;
      var byline = document.createElement('span');
      byline.className = 'card-byline';
      byline.textContent = 'by ' + (entry.author && entry.author[0] && entry.author[0].name ? entry.author[0].name.$t : 'The editorial team');
      var meta = document.createElement('div');
      meta.className = 'card-meta';
      var date = entry.published && new Date(entry.published.$t);
      if (date && !isNaN(date.getTime())) {
        var time = document.createElement('time');
        time.dateTime = date.toISOString();
        time.textContent = date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
        meta.appendChild(time);
      }
      var read = document.createElement('span');
      read.className = 'card-read';
      read.textContent = 'Read story';
      meta.appendChild(read);
      var arrow = document.createElement('span');
      arrow.className = 'card-arrow';
      arrow.setAttribute('aria-hidden', 'true');
      arrow.textContent = '\u2192';
      meta.appendChild(arrow);
      content.appendChild(category);
      content.appendChild(title);
      content.appendChild(byline);
      content.appendChild(meta);
      anchor.appendChild(media);
      anchor.appendChild(content);
      article.appendChild(anchor);
      return article;
    }
    function loadLabel(label, current) {
      if (!home || !label) return Promise.resolve([]);
      try {
        var url = new URL('feeds/posts/summary/-/' + encodeURIComponent(label), home);
        url.searchParams.set('alt', 'json');
        url.searchParams.set('max-results', '6');
        return fetch(url.href, { credentials: 'same-origin' }).then(function (response) {
          if (!response.ok) throw new Error('Feed unavailable');
          return response.json();
        }).then(function (data) {
          return ((data.feed && data.feed.entry) || []).filter(function (entry) {
            var link = (entry.link || []).find(function (item) { return item.rel === 'alternate'; });
            return link && (!current || pathKey(link.href) !== pathKey(current));
          }).slice(0, 3);
        }).catch(function () { return []; });
      } catch (e) { return Promise.resolve([]); }
    }
    function populate(section, grid, label, current) {
      if (!section || !grid) return;
      loadLabel(label, current).then(function (entries) {
        entries.forEach(function (entry) { var card = createFeedCard(entry); if (card) grid.appendChild(card); });
        if (grid.children.length) section.hidden = false;
      });
    }
    var related = document.getElementById('relatedPosts');
    if (related) populate(related, document.getElementById('relatedGrid'), related.dataset.label, related.dataset.current);
    var shelves = document.getElementById('categoryShelves');
    if (shelves) {
      var loadShelves = function () {
        shelves.querySelectorAll('.category-shelf').forEach(function (section) {
          populate(section, section.querySelector('.shelf-grid'), section.dataset.label, '');
        });
      };
      if ('IntersectionObserver' in window) {
        var observer = new IntersectionObserver(function (entries) {
          if (entries.some(function (entry) { return entry.isIntersecting; })) { observer.disconnect(); loadShelves(); }
        }, { rootMargin: '600px' });
        observer.observe(shelves);
      } else {
        loadShelves();
      }
    }
  }());
  //
